<?php
require_once __DIR__.'/includes/functions.php';require_once __DIR__.'/includes/csrf.php';
$adminLogin=($_GET['admin']??'')==='1'||($_POST['admin_login']??'')==='1';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';$s=db()->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$s->execute([$email]);$u=$s->fetch();if($u&&$u['is_active']&&(!$adminLogin||$u['role']==='admin')&&password_verify($password,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];flash('success','Signed in successfully.');redirect($u['role']==='admin'?'/admin/dashboard.php':'/');}flash('error',$adminLogin?'Use an active admin account to continue.':'Invalid email or password.');}
$pageTitle=$adminLogin?'Admin Login':'Login';include __DIR__.'/includes/header.php';?><form class="form-card" method="post" style="max-width:520px"><h1><?=$adminLogin?'Admin sign in':'Welcome back'?></h1><?php if($adminLogin):?><p class="muted">Sign in with your administrator account to manage RADIUS.</p><?php endif;?><?=csrf_field()?><?php if($adminLogin):?><input type="hidden" name="admin_login" value="1"><?php endif;?><div class="stack"><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="btn"><?=$adminLogin?'Admin Login':'Login'?></button></div></form><?php include __DIR__.'/includes/footer.php';?>